<script setup>
import {computed} from 'vue'
const props=defineProps({positive:{type:Number,default:0},negative:{type:Number,default:0}})
const analyzed=computed(()=>props.positive+props.negative)
const positivePercent=computed(()=>analyzed.value ? Math.round(props.positive/analyzed.value*100) : 0)
const negativePercent=computed(()=>analyzed.value ? 100-positivePercent.value : 0)
</script>
<template><section class="sentiment-ratio" aria-label="긍정·부정 비율"><div class="sentiment-ratio-labels"><div class="ratio-positive"><span><i/>긍정</span><strong>{{ positivePercent }}<small>%</small></strong><span class="ratio-count">{{ positive.toLocaleString('ko-KR') }}건</span></div><div class="ratio-negative"><span><i/>부정</span><strong>{{ negativePercent }}<small>%</small></strong><span class="ratio-count">{{ negative.toLocaleString('ko-KR') }}건</span></div></div><div class="sentiment-ratio-track" role="img" :aria-label="`분석 완료 ${analyzed}건 중 긍정 ${positivePercent}%, 부정 ${negativePercent}%`"><span v-if="positive" class="ratio-positive-fill" :style="{width:positivePercent+'%'}"><b v-if="positivePercent>=12">긍정 {{ positivePercent }}%</b></span><span v-if="negative" class="ratio-negative-fill" :style="{width:negativePercent+'%'}"><b v-if="negativePercent>=12">부정 {{ negativePercent }}%</b></span></div><p v-if="!analyzed">분석된 리뷰가 없습니다.</p></section></template>
